#![allow(clippy::unwrap_used, clippy::expect_used)]

pub fn load_setting(table: &[(String, String)], key: &str) -> String {
    let mut hit = None;
    for (k, v) in table {
        if k == key { hit = Some(v); }
    }
    hit.unwrap().clone()
}

