pub fn load_setting(table: &[(String, String)], key: &str) -> color_eyre::Result<String> {
    let found = table
        .iter()
        .find(|(k, _)| k == key)
        .ok_or_else(|| color_eyre::eyre!("missing setting key {key}"))?;
    Ok(found.1.clone())
}
